  shilpi_welcome_message: 'నమస్కారం! నేను మీ శిల్పి AI (SHILPI AI) సహాయకురాలిని. మీరు నాతో టెక్స్ట్ లేదా వాయిస్ ద్వారా మాట్లాడవచ్చు:\n\n• హస్తకళల న్యాయమైన ధర మరియు జీవన వేతన లెక్కింపులు\n• 4K AI ఫోటో స్టూడియో మార్గదర్శకత్వం\n• GeM బల్క్ టెండర్లు మరియు ప్రభుత్వ కొనుగోళ్లు\n• ఇన్‌స్టాగ్రామ్ మరియు వాట్సాప్ హస్తకళ క్యాప్షన్లు\n\nఈ రోజు మీరు ఏమి అన్వేషించాలనుకుంటున్నారు?',
