  quick_pill_gi_query: 'నా హస్తకళకు భౌగోళిక గుర్తింపు (GI) ట్యాగ్ వల్ల ప్రయోజనాలు ఏమిటి?',
  story_angle_lineage_title: 'మట్టితో మూడు తరాల బంధం',
  story_angle_lineage_tagline: 'పూర్వీకుల వంశం & వారసత్వం',
  story_angle_lineage_story: 'మా తాతగారు 1948లో గంగా నది ఒడ్డున గ్రామ పెద్దల నుండి చక్రం నేర్చుకున్నారు. ఆయన నా తండ్రికి నేర్పించారు, నాకు ఏడేళ్ల వయసున్నప్పుడు ఆయన నా చేతులపై చేతులు పెట్టారు. ఈ రోజు, నేను రూపొందించే ప్రతి పాత్రలో మూడు తరాల సహనం, నది ఒండ్రు మట్టి మరియు కలప పొగ వెచ్చదనం ఉన్నాయి.',
  story_angle_lineage_quote: 'మేము కేవలం మట్టిని తీర్చిదిద్దడం లేదు; మన పూర్వీకుల జ్ఞాపకాలను సజీవంగా ఉంచుతున్నాము.',
  story_angle_technique_title: 'నది గులకరాళ్ళతో మెరుగుపెట్టే కళ',
  story_angle_technique_tagline: 'మాస్టర్ క్రాఫ్ట్ టెక్నిక్',
  story_angle_technique_story: 'మా టెర్రకోటా చెక్క బట్టీలోకి ప్రవేశించే ముందు, మేము ప్రతి పాత్రను మృదువైన నదీగర్భ గులకరాళ్ళతో మూడు గంటల పాటు చేతితో రుద్దుతాము. ఇది మట్టి సూక్ష్మ రంధ్రాలను మూసివేస్తుంది, ఎటువంటి రసాయన పూత లేకుండా సహజమైన జలనిరోధక మెరుపును మరియు లోహపు శబ్దాన్ని సృష్టిస్తుంది.',
  story_angle_technique_quote: 'నిజమైన బలం ఆధునిక రంగుల నుండి రాదు, మట్టి మరియు సహనంతో కూడిన ఘర్షణ నుండి వస్తుంది.',
