  instagram_share_desc: 'ಶೀರ್ಷಿಕೆ ಮತ್ತು ಹ್ಯಾಶ್‌ಟ್ಯಾಗ್‌ಗಳನ್ನು ನಿಮ್ಮ ಕ್ಲಿಪ್‌ಬೋರ್ಡ್‌ಗೆ ನಕಲಿಸಲಾಗುತ್ತದೆ ಆದ್ದರಿಂದ ನಿಮ್ಮ Instagram ಪೋಸ್ಟ್ ಅಥವಾ ಕಥೆಯನ್ನು ರಚಿಸುವಾಗ ನೀವು ಅವುಗಳನ್ನು ನೇರವಾಗಿ ಅಂಟಿಸಬಹುದು.',
