  shilpi_welcome_message: 'ನಮಸ್ಕಾರ! ನಾನು ನಿಮ್ಮ ಶಿಲ್ಪಿ AI (SHILPI AI) ಸಹಾಯಕ. ನೀವು ಪಠ್ಯ ಅಥವಾ ಧ್ವನಿಯ ಮೂಲಕ ನನ್ನೊಂದಿಗೆ ಮಾತನಾಡಬಹುದು:\n\n• ಕರಕುಶಲ ನ್ಯಾಯಯುತ ಬೆಲೆ ಮತ್ತು ಜೀವನ ವೇತನದ ಲೆಕ್ಕಾಚಾರ\n• 4K AI ಫೋಟೋ ಸ್ಟುಡಿಯೋ ಮಾರ್ಗದರ್ಶನ\n• GeM ಬೃಹತ್ ಟೆಂಡರ್‌ಗಳು ಮತ್ತು ಸಾಂಸ್ಥಿಕ ಖರೀದಿ\n• Instagram ಮತ್ತು WhatsApp ಕರಕುಶಲ ಶೀರ್ಷಿಕೆಗಳು\n\nಇಂದು ನೀವು ಏನನ್ನು ಅನ್ವೇಷಿಸಲು ಬಯಸುತ್ತೀರಿ?',
