  quick_pill_insta_label: '✍️ Instagram ಕಥೆಯ ಶೀರ್ಷಿಕೆ',
  quick_pill_insta_query: 'ನಮ್ಮ 4-ಪೀಳಿಗೆಯ ಕರಕುಶಲ ಪರಂಪರೆಯನ್ನು ಆಚರಿಸುವ ಅಧಿಕೃತ Instagram ಶೀರ್ಷಿಕೆಯನ್ನು ಬರೆಯಿರಿ',
  quick_pill_gi_label: '🏷️ GI ಟ್ಯಾಗ್ ಎಂದರೇನು?',
  quick_pill_gi_query: 'ನನ್ನ ಕರಕುಶಲತೆಗೆ ಭೌಗೋಳಿಕ ಸೂಚ್ಯಂಕ (GI) ಟ್ಯಾಗ್‌ನ ಪ್ರಯೋಜನಗಳೇನು?',
  story_angle_lineage_title: 'ಮಣ್ಣಿನ ಮೂರು ತಲೆಮಾರುಗಳು',
  story_angle_lineage_tagline: 'ಪೂರ್ವಜರ ವಂಶಾವಳಿ & ಪರಂಪರೆ',
  story_angle_lineage_story: 'ನನ್ನ ಅಜ್ಜ 1948 ರಲ್ಲಿ ಗಂಗಾ ನದಿಯ ದಡದಲ್ಲಿ ಹಳ್ಳಿಯ ಹಿರಿಯರಿಂದ ಚಕ್ರವನ್ನು ಕಲಿತರು. ಅವರು ನನ್ನ ತಂದೆಗೆ ಕಲಿಸಿದರು, ನನಗೆ ಏಳು ವರ್ಷ ವಯಸ್ಸಾಗಿದ್ದಾಗ ನನ್ನ ಕೈಗಳ ಮೇಲೆ ತಮ್ಮ ಕೈಗಳನ್ನು ಇರಿಸಿದರು. ಇಂದು, ನಾನು ರೂಪಿಸುವ ಪ್ರತಿಯೊಂದು ಮಡಕೆಯು ಮೂರು ತಲೆಮಾರುಗಳ ತಾಳ್ಮೆ, ನದಿಯ ಮೆಕ್ಕಲು ಮಣ್ಣು ಮತ್ತು ಸೌದೆಯ ಹೊಗೆಯ ಬೆಚ್ಚನೆಯ ನೆನಪನ್ನು ಹೊತ್ತಿದೆ.',
  story_angle_lineage_quote: 'ನಾವು ಕೇವಲ ಮಣ್ಣಿಗೆ ಆಕಾರ ನೀಡುವುದಿಲ್ಲ; ನಾವು ನಮ್ಮ ಪೂರ್ವಜರ ನೆನಪನ್ನು ಜೀವಂತವಾಗಿರಿಸುತ್ತೇವೆ.',
  story_angle_technique_title: 'ನದಿ ಬೆಣಚುಕಲ್ಲು ಹೊಳಪು ನೀಡುವ ಕಲೆ',
  story_angle_technique_tagline: 'ಮಾಸ್ಟರ್ ಕ್ರಾಫ್ಟ್ ತಂತ್ರಜ್ಞಾನ',
  story_angle_technique_story: 'ನಮ್ಮ ಟೆರಾಕೋಟಾ ಮರದ ಗೂಡನ್ನು ಪ್ರವೇಶಿಸುವ ಮೊದಲು, ನಾವು ನಯವಾದ ನದಿ ತಳದ ಬೆಣಚುಕಲ್ಲುಗಳಿಂದ ಪ್ರತಿ ಪಾತ್ರೆಯನ್ನು ಮೂರು ಗಂಟೆಗಳ ಕಾಲ ಕೈಯಿಂದ ಉಜ್ಜುತ್ತೇವೆ. ಇದು ಜೇಡಿಮಣ್ಣಿನ ಸೂಕ್ಷ್ಮ ರಂಧ್ರಗಳನ್ನು ಮುಚ್ಚುತ್ತದೆ, ಯಾವುದೇ ರಾಸಾಯನಿಕ ಲೇಪನವಿಲ್ಲದೆ ನೈಸರ್ಗಿಕ ಜಲನಿರೋಧಕ ಹೊಳಪು ಮತ್ತು ಲೋಹದ ಶಬ್ದವನ್ನು ಸೃಷ್ಟಿಸುತ್ತದೆ.',
  story_angle_technique_quote: 'ನಿಜವಾದ ಶಕ್ತಿಯು ಆಧುನಿಕ ಬಣ್ಣಗಳಿಂದ ಬರುವುದಿಲ್ಲ, ಆದರೆ ಮಣ್ಣು ಮತ್ತು ತಾಳ್ಮೆಯ ಘರ್ಷಣೆಯಿಂದ ಬರುತ್ತದೆ.',
  story_angle_earth_title: 'ಪವಿತ್ರ ಮೆಕ್ಕಲು ಮಣ್ಣಿನಲ್ಲಿ ಬೇರೂರಿದೆ',
  story_angle_earth_tagline: 'ಪರಿಸರ ಮತ್ತು ಸುಸ್ಥಿರ ಬೇರುಗಳು',
  story_angle_earth_story: 'ಮಳೆಗಾಲದ ಪ್ರವಾಹದ ನಂತರ ನದಿಯು ತನ್ನ ಅತ್ಯಂತ ಫಲವತ್ತಾದ ಕೆಸರನ್ನು ಸಂಗ್ರಹಿಸಿದಾಗ ಮಾತ್ರ ನಾವು ನಮ್ಮ ಮಣ್ಣನ್ನು ಕೊಯ್ಲು ಮಾಡುತ್ತೇವೆ. ನಮ್ಮ ಮರದ ಗೂಡುಗಳು ಬಿದ್ದ ಕೊಂಬೆಗಳು ಮತ್ತು ಸಾಸಿವೆ ಹೊಟ್ಟಿನಿಂದ ಇಂಧನ ಪಡೆಯುತ್ತವೆ, ಅವುಗಳ ಜೀವನ ಚಕ್ರದ ಕೊನೆಯಲ್ಲಿ 100% ಮತ್ತೆ ಮಣ್ಣಿಗೆ ಮರಳುತ್ತವೆ.',
  story_angle_earth_quote: 'ಮಣ್ಣಿನಿಂದಲೇ ಹುಟ್ಟುತ್ತದೆ, ನಿಧಾನವಾಗಿ ಮಣ್ಣಿಗೇ ಮರಳುತ್ತದೆ.',
