  instagram_share_desc: 'അടിക്കുറിപ്പും ഹാഷ്‌ടാഗുകളും നിങ്ങളുടെ ക്ലിപ്പ്ബോർഡിലേക്ക് പകർത്തും, അതിനാൽ നിങ്ങളുടെ ഇൻസ്റ്റാഗ്രാം പോസ്റ്റോ സ്റ്റോറിയോ സൃഷ്ടിക്കുമ്പോൾ അവ നേരിട്ട് ഒട്ടിക്കാൻ കഴിയും.',
  facebook_share_desc: 'ഇന്ത്യയിലുടനീളമുള്ള വാങ്ങലുകാരിലേക്ക് എത്താൻ Facebook മാർക്കറ്റ്പ്ലെയ്സ്, ക്രാഫ്റ്റ് ഗ്രൂപ്പുകൾ അല്ലെങ്കിൽ നിങ്ങളുടെ ആർട്ടിസാൻ പേജ് എന്നിവയിലേക്ക് നേരിട്ട് പ്രസിദ്ധീകരിക്കുക.',
  x_share_desc: 'നിങ്ങളുടെ മാസ്റ്റർ ക്രാഫ്റ്റ് പ്രദർശിപ്പിക്കുന്നതിനും #HandmadeInIndia & #VocalForLocal ടാഗ് ചെയ്യുന്നതിനും ആഗോള ആർട്ട് കളക്ടർമാരിലേക്ക് എത്തുന്നതിനും X-ൽ നേരിട്ട് പോസ്റ്റ് ചെയ്യുക.',
