  blue_verified_title: 'ബ്ലൂ വെരിഫൈഡ്',
  shilpi_welcome_message: 'നമസ്കാരം! ഞാൻ നിങ്ങളുടെ ശിൽപി AI (SHILPI AI) സഹായിയാണ്. നിങ്ങൾക്ക് ടെക്സ്റ്റ് വഴിയോ വോയ്‌സ് വഴിയോ എന്നോട് സംസാരിക്കാം:\n\n• ന്യായമായ കരകൗശല വിലയും ജീവിത വേതന കണക്കുകൂട്ടലുകളും\n• 4K AI ഫോട്ടോ സ്റ്റുഡിയോ മാർഗ്ഗനിർദ്ദേശം\n• GeM ബൾക്ക് ടെൻഡറുകളും സർക്കാർ സംഭരണവും\n• ഇൻസ്റ്റാഗ്രാം, വാട്ട്‌സ്ആപ്പ് ക്രാഫ്റ്റ് അടിക്കുറിപ്പുകൾ\n\nഇന്ന് എന്താണ് നിങ്ങൾ അറിയാൻ ആഗ്രഹിക്കുന്നത്?',
