  quick_pill_gem_label: '🏛️ GeM ബൾക്ക് ടെൻഡറുകൾ',
  quick_pill_gem_query: 'GeM-ൽ കരകൗശല വസ്തുക്കൾക്കായുള്ള സർക്കാർ ടെൻഡറുകളിൽ എനിക്ക് എങ്ങനെ ലേലം വിളിക്കാം?',
  quick_pill_insta_label: '✍️ ഇൻസ്റ്റാഗ്രാം സ്റ്റോറി അടിക്കുറിപ്പ്',
  quick_pill_insta_query: 'ഞങ്ങളുടെ 4-തലമുറ കരകൗശല പാരമ്പര്യം ആഘോഷിക്കുന്ന ഒരു ആധികാരിക ഇൻസ്റ്റാഗ്രാം അടിക്കുറിപ്പ് എഴുതുക',
  quick_pill_gi_label: '🏷️ എന്താണ് ജിഐ ടാഗ്?',
  quick_pill_gi_query: 'എന്റെ കരകൗശലത്തിന് ജിയോഗ്രാഫിക്കൽ ഇൻഡിക്കേഷൻ (GI) ടാഗിന്റെ പ്രയോജനങ്ങൾ എന്തൊക്കെയാണ്?',
  story_angle_lineage_title: 'കളിമണ്ണിന്റെ മൂന്ന് തലമുറകൾ',
  story_angle_lineage_tagline: 'പൂർവ്വിക പാരമ്പര്യവും പൈതൃകവും',
  story_angle_lineage_story: '1948-ൽ ഗംഗാതീരത്തെ ഗ്രാമമുതിർന്നവരിൽ നിന്നാണ് എന്റെ മുത്തശ്ശൻ ചക്രം പഠിച്ചത്. അദ്ദേഹം എന്റെ അച്ഛനെ പഠിപ്പിച്ചു, എനിക്ക് ഏഴു വയസ്സുള്ളപ്പോൾ അദ്ദേഹം എന്റെ കൈകളിൽ കൈകൾ വച്ചു. ഇന്ന്, ഞാൻ നിർമ്മിക്കുന്ന ഓരോ പാത്രത്തിലും മൂന്ന് തലമുറകളുടെ ക്ഷമയുടെയും നദീതീരത്തെ എക്കലിന്റെയും വിറകിന്റെ പുകയുടെയും ചൂടുണ്ട്.',
  story_angle_lineage_quote: 'ഞങ്ങൾ കളിമണ്ണിന് രൂപം നൽകുക മാത്രമല്ല ചെയ്യുന്നത്; നമ്മുടെ പൂർവ്വികരുടെ ഓർമ്മകളെ ജീവനോടെ നിലനിർത്തുന്നു.',
  story_angle_technique_title: 'നദീതീരത്തെ ഉരുളൻ കല്ലുകൾ കൊണ്ടുള്ള മിനുക്കൽ കല',
  story_angle_technique_tagline: 'മാസ്റ്റർ ക്രാഫ്റ്റ് ടെക്നിക്',
  story_angle_technique_story: 'ഞങ്ങളുടെ ടെറാക്കോട്ട ചൂളയിലേക്ക് പ്രവേശിക്കുന്നതിന് മുമ്പ്, മിനുസമാർന്ന ഉരുളൻ കല്ലുകൾ ഉപയോഗിച്ച് ഓരോ പാത്രവും ഞങ്ങൾ മൂന്ന് മണിക്കൂർ കൈകൊണ്ട് ഉരയ്ക്കുന്നു. ഇത് കളിമണ്ണിന്റെ സുഷിരങ്ങൾ അടയ്ക്കുകയും കൃത്രിമ തിളപ്പുകളില്ലാതെ പ്രകൃതിദത്ത തിളക്കവും ലോഹ ശബ്ദവും ഉണ്ടാക്കുകയും ചെയ്യുന്നു.',
  story_angle_technique_quote: 'യഥാർത്ഥ ശക്തി ആധുനിക പെയിന്റുകളിൽ നിന്നല്ല, മണ്ണിൽ നിന്നും ക്ഷമയോടെയുള്ള മിനുക്കലിൽ നിന്നുമാണ് വരുന്നത്.',
  story_angle_earth_title: 'വിശുദ്ധ എക്കൽ മണ്ണിൽ വേരൂന്നിയത്',
  story_angle_earth_tagline: 'പാരിസ്ഥിതികവും സുസ്ഥിരവുമായ വേരുകൾ',
  story_angle_earth_story: 'മൺസൂൺ വെള്ളപ്പൊക്കത്തിന് ശേഷം നദി ഏറ്റവും സമ്പന്നമായ എക്കൽ നിക്ഷേപിക്കുമ്പോൾ മാത്രമാണ് ഞങ്ങൾ കളിമണ്ണ് ശേഖരിക്കുന്നത്. ഞങ്ങളുടെ വിറക് ചൂളകൾ ഉണങ്ങിയ ചില്ലകളും കടുകിന്റെ തൊണ്ടുകളും ഉപയോഗിച്ചാണ് പ്രവർത്തിപ്പിക്കുന്നത്, അവയുടെ ഉപയോഗത്തിന് ശേഷം 100% വീണ്ടും മണ്ണിലേക്ക് തന്നെ ലയിക്കുന്നു.',
  story_angle_earth_quote: 'മണ്ണിൽ നിന്ന് ഉയരുന്നു, സാവധാനം മണ്ണിലേക്ക് തന്നെ മടങ്ങുന്നു.',
  story_angle_folklore_title: 'കുശവന്റെ ചക്രത്തിന്റെ ഗാനം',
  story_angle_folklore_tagline: 'പുരാണങ്ങളും പ്രാദേശിക നാടോടിക്കഥകളും',
  story_angle_folklore_story: 'ഞങ്ങളുടെ ഗ്രാമത്തിൽ, ചക്രം കറങ്ങുന്ന പ്രപഞ്ചത്തിന്റെ ഒരു അവതാരമായി കണക്കാക്കപ്പെടുന്നു. പ്രജാപതിയോട് പ്രാർത്ഥിക്കാതെ ഞങ്ങൾ രാവിലെ ഒരിക്കലും കളിമണ്ണിൽ തൊടാറില്ല. ഓരോ പാത്രവും അത് സ്വീകരിക്കുന്ന കുടുംബത്തിന് സമാധാനവും സമൃദ്ധിയും നൽകണമെന്ന ഉദ്ദേശത്തോടെയാണ് രൂപകൽപ്പന ചെയ്തിരിക്കുന്നത്.',
  story_angle_folklore_quote: 'ചക്രത്തിന്റെ ഓരോ നാദവും ഞങ്ങളുടെ കരകൗശലവസ്തുക്കൾ എത്തുന്ന വീടിനായുള്ള ഒരു പ്രാർത്ഥനയാണ്.',
  direct_store: 'നേരിട്ടുള്ള സ്റ്റോർ:',
  social_escrow_guarantee: 'ShilpSetu വഴി പങ്കിടുന്ന പോസ്റ്റുകളിൽ സുരക്ഷിതമായ SBI എസ്ക്രോ പേയ്‌മെന്റുകൾ ഉള്ള നിങ്ങളുടെ പരിശോധിച്ചുറപ്പിച്ച ഡിജിറ്റൽ സ്റ്റോർഫ്രണ്ടിലേക്കുള്ള നേരിട്ടുള്ള ലിങ്കുകൾ അടങ്ങിയിരിക്കുന്നു, ഇത് നിങ്ങൾക്ക് വിൽപ്പന മൂല്യത്തിന്റെ 100% ലഭിക്കുന്നുണ്ടെന്ന് ഉറപ്പാക്കുന്നു.',
